// One-event test configuration: EQ for 2026-10-27
return [{
  json: {
    eventtype: 'EQ',
    fromdate: '2026-10-27',
    todate: '2026-10-27',
    pagenumber: 1,
    cursor_date: 'test_one_event',
    next_cursor_date: 'test_one_event',
    polling: true
  }
}];

var pages = $input.all();
var combo = $("Loop Event-Year Combos").first().json;
var out = [];
for (var i = 0; i < pages.length; i++) {
  var feats = (pages[i].json && pages[i].json.features) || [];
  for (var k = 0; k < feats.length; k++) {
    var f = feats[k] || {};
    var p = f.properties || {};
    var g = f.geometry || {};
    var coords = g.coordinates || [null, null];
    var sev = p.severitydata || {};
    var urls = p.url || {};
    out.push({ json: {
      eventtype: p.eventtype || combo.eventtype,
      eventid: (p.eventid === undefined ? null : p.eventid),
      episodeid: (p.episodeid === undefined ? null : p.episodeid),
      name: p.name || null,
      description: p.description || null,
      alertlevel: p.alertlevel || null,
      country: p.country || null,
      iso3: p.iso3 || null,
      fromdate: p.fromdate || null,
      todate: p.todate || null,
      datemodified: p.datemodified || null,
      longitude: (coords[0] === undefined ? null : coords[0]),
      latitude: (coords[1] === undefined ? null : coords[1]),
      severity: (sev.severity === undefined ? null : sev.severity),
      severity_unit: sev.severityunit || null,
      severity_text: sev.severitytext || null,
      source: p.source || null,
      report_url: urls.report || null,
      details_url: urls.details || null,
      raw_json: JSON.stringify(f)
    } });
  }
}
if (out.length === 0) {
  out.push({ json: { _empty: true, eventtype: combo.eventtype, file_key: combo.file_key } });
}
return out;

const source = $('Loop Events').first().json;
const api = JSON.parse(source.raw_json);
const reply = $input.first().json;
const page = Array.isArray(reply.body) ? reply.body[0] : null;
let valid = false;
if (page && page.status === 200 && !page.error && typeof page.content === 'string' && page.content.length > 0) {
  if (typeof page.url === 'string' && page.url.toLowerCase().includes('gdacs.org/report.aspx')) {
    valid = true;
  }
}
const scrape = {
  source_url: source.report_url,
  captured_at: new Date().toISOString(),
  status: valid ? 'complete' : (source.report_url ? 'failed' : 'missing'),
  content: valid ? page.content : null,
  metadata: valid ? (page.metadata ?? null) : null
};
const event_id = 'gdacs_' + source.eventtype + '_' + source.eventid + '_' + source.episodeid;
const artifact_path = 'gdacs/events/' + source.eventtype + '/' + source.eventid + '-' + source.episodeid + '/' + $execution.id + '.json';
const event = {
  schema_version: 1,
  event_id,
  run_id: String($execution.id),
  environment_id: 'shared',
  collected_at: scrape.captured_at,
  source_url: source.report_url,
  complete: valid,
  limitations: valid ? [] : ['Report page not captured; API record preserved.'],
  provenance: {
    api: 'gdacs',
    report: valid ? 'spider_unlimited_scrape' : null
  },
  api,
  scrape
};
const basin_event = {
  id: event_id,
  event_id: event_id,
  source_id: 'src_gdacs',
  publisher: 'GDACS',
  headline: source.name || event_id,
  product: 'ops',
  tenant_id: 'shared',
  workspace_id: 'shared',
  captured_at: source.datemodified || scrape.captured_at
};
return [{
  json: {
    ...source,
    raw_json: JSON.stringify({ api, artifact_path, scrape_status: scrape.status }),
    event_id,
    artifact_path,
    event,
    basin_event
  }
}];

const body = $input.first().json;
const committed = body.result?.committed ?? body.committed ?? body.accepted ?? 0;
if (committed !== 1 && body.success !== true) {
  throw new Error('Basin did not confirm one event: ' + JSON.stringify(body).slice(0, 300));
}
const event = $('Compile Event').first().json;
const envelope = {
  event_id: event.event_id,
  platform: 'v2',
  event_type: 'gdacs.completed',
  connector: 'gdacs',
  run_id: String($execution.id),
  environment_id: 'shared',
  occurred_at: new Date().toISOString(),
  payload: {
    artifact_bucket: 'harvy-artifacts',
    artifact_path: event.artifact_path,
    gdacs_event_id: event.eventid,
    episode_id: event.episodeid,
    scrape_status: event.event.scrape.status,
    basin_ingested: true
  }
};
return [{
  json: {
    event_id: event.event_id,
    artifact_path: event.artifact_path,
    k2_content: Buffer.from(JSON.stringify(envelope), 'utf8').toString('base64')
  }
}];

const body = $input.first().json;
const event = $('Verify Basin').first().json;
return [{
  json: {
    event_id: event.event_id,
    artifact_path: event.artifact_path,
    completed: true,
    k2_status: body.success === true ? 'recorded' : 'k2_http_input_disabled'
  }
}];

const window = $('Build Fetch Queue').first().json;
const row = $('Read Backfill Cursor').first().json;
return [{
  json: {
    state_key: 'gdacs_backfill',
    cursor_date: row.cursor_date,
    last_success_at: new Date().toISOString()
  }
}];

